"""Merge type profiles into the asset index and emit the reverse lookup table.

Two products, deliberately separate:
  * asset_index.json -- geometry facts, regenerated by asset_scan.py. Never edit
    it by hand; the scanner owns it.
  * assets/profiles/_type_profiles.json -- documented type data, hand-curated
    with sources. This tool copies profiles onto their meshes and writes the
    generic-name -> type table the dataset docs refer to.

Keeping them separate means a rescan can never silently discard curated
signature data.
"""
import json
import os

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
INDEX = os.path.join(ROOT, "assets", "asset_index.json")
PROFILES = os.path.join(ROOT, "assets", "profiles", "_type_profiles.json")
LOOKUP = os.path.join(ROOT, "assets", "profile_lookup.json")


def main():
    index = json.load(open(INDEX, encoding="utf-8"))
    profs = json.load(open(PROFILES, encoding="utf-8"))["profiles"]

    by_key = {(m["category"], m["name"]): m for m in index["models"]}
    for m in index["models"]:
        m.pop("profiles", None)

    attached, missing = [], []
    for p in profs:
        cat, _, name = p["asset"].partition("/")
        m = by_key.get((cat, name))
        if m is None:
            missing.append(p["asset"])
            continue
        m.setdefault("profiles", []).append(
            {k: v for k, v in p.items() if k != "asset"})
        attached.append(p["asset"])

    # Reverse table: generic mesh name -> the concrete types it may stand for.
    # A proxy silhouette often fits its type only approximately; carrying the
    # mismatch here keeps it visible instead of letting it become a silent lie
    # in a dataset caption.
    lookup = {}
    for m in index["models"]:
        plist = m.get("profiles") or []
        if not plist:
            continue
        key = "%s/%s" % (m["category"], m["name"])
        lookup[key] = dict(
            generic_name=m["name"],
            category=m["category"],
            types=[dict(
                name=p["name"],
                confidence=p.get("confidence", "unstated"),
                rcs_value_m2=(p.get("rcs") or {}).get("value_m2"),
                rcs_band=(p.get("rcs") or {}).get("band"),
                real_span_m=(p.get("real_size_m") or {}).get("span"),
                real_length_m=(p.get("real_size_m") or {}).get("length"),
                sources=[(p.get("rcs") or {}).get("source")] if (p.get("rcs") or {}).get("source") else [],
            ) for p in plist],
        )

    json.dump(index, open(INDEX, "w", encoding="utf-8"), ensure_ascii=False, indent=1)
    json.dump(dict(schema=1, count=len(lookup), lookup=lookup),
              open(LOOKUP, "w", encoding="utf-8"), ensure_ascii=False, indent=1)

    print("attached %d profiles to %d models" % (len(attached), len(lookup)))
    if missing:
        print("MISSING meshes for profiles: %s" % ", ".join(missing))
    print("lookup -> %s" % os.path.relpath(LOOKUP, ROOT))


if __name__ == "__main__":
    main()
